package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeRow_TriageGen2Test {

    private KeyedObjects2D keyedObjects2D;

    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }

    @Test
    public void testRemoveRow_ExistingKey() {
        // Arrange
        Comparable rowKey1 = "Row1";
        Comparable rowKey2 = "Row2";
        Comparable colKey = "Col1";

        keyedObjects2D.addObject("Data1", rowKey1, colKey);
        keyedObjects2D.addObject("Data2", rowKey2, colKey);

        assertEquals(2, keyedObjects2D.getRowCount());

        // Act
        keyedObjects2D.removeRow(rowKey1);

        // Assert
        assertEquals(1, keyedObjects2D.getRowCount());
        assertEquals(rowKey2, keyedObjects2D.getRowKey(0));
        assertEquals("Data2", keyedObjects2D.getObject(0, 0));
    }

    @Test
    public void testRemoveRow_NonExistingKey() {
        // Arrange
        Comparable rowKey1 = "Row1";
        Comparable colKey = "Col1";
        keyedObjects2D.addObject("Data1", rowKey1, colKey);

        // Act & Assert
        // Assuming getRowIndex returns -1 if key is not found, 
        // and removeRow(int) handles -1 or throws exception.
        // Based on standard JFreeChart patterns, we test the behavior when key is missing.
        try {
            keyedObjects2D.removeRow("NonExistent");
        } catch (IndexOutOfBoundsException | IllegalArgumentException e) {
            // Success if it throws an error for an invalid index
        } catch (Exception e) {
            throw new AssertionError("Unexpected exception type: " + e.getClass().getName());
        }
    }

    @Test
    public void testRemoveRow_EmptyDataset() {
        // Arrange
        Comparable rowKey = "Row1";

        // Act & Assert
        try {
            keyedObjects2D.removeRow(rowKey);
        } catch (Exception e) {
            // Catching potential exceptions from removeRow(-1)
        }
        assertEquals(0, keyedObjects2D.getRowCount());
    }

    @Test
    public void testRemoveRow_LastRow() {
        // Arrange
        Comparable rowKey1 = 1;
        Comparable rowKey2 = 2;
        Comparable colKey = "C";
        keyedObjects2D.addObject("D1", rowKey1, colKey);
        keyedObjects2D.addObject("D2", rowKey2, colKey);

        // Act
        keyedObjects2D.removeRow(rowKey2);

        // Assert
        assertEquals(1, keyedObjects2D.getRowCount());
        assertEquals(rowKey1, keyedObjects2D.getRowKey(0));
    }

    @Test
    public void testRemoveRow_FirstRow() {
        // Arrange
        Comparable rowKey1 = 1;
        Comparable rowKey2 = 2;
        Comparable colKey = "C";
        keyedObjects2D.addObject("D1", rowKey1, colKey);
        keyedObjects2D.addObject("D2", rowKey2, colKey);

        // Act
        keyedObjects2D.removeRow(rowKey1);

        // Assert
        assertEquals(1, keyedObjects2D.getRowCount());
        assertEquals(rowKey2, keyedObjects2D.getRowKey(0));
    }
}
